//https://stackoverflow.com/questions/66186240/how-to-use-controls-from-built-in-uitypeeditorsThe Controlusing System;using System.ComponentModel;using System.ComponentModel.Design;using System.Drawing;using System.Drawing.Design;using System.Windows.Forms;using System.Windows.Forms.Design;public class MyTestControl : Control{    [Editor(typeof(MyTestClassEditor), typeof(UITypeEditor))]    [DesignerSerializationVisibility(DesignerSerializationVisibility.Content)]    public MyTestClass MyTestProperty { get; set; } = new MyTestClass();    protected override void OnPaint(PaintEventArgs e)    {        base.OnPaint(e);        if (MyTestProperty != null &&            MyTestProperty.MyTestImageProperty != null)            e.Graphics.DrawImage(MyTestProperty.MyTestImageProperty,                ClientRectangle.Location);    }}public class MyTestClass{    public Image MyTestImageProperty { get; set; }}UITypeEditorpublic class MyTestClassEditor : UITypeEditor{    public override UITypeEditorEditStyle GetEditStyle(        ITypeDescriptorContext context)    {        return UITypeEditorEditStyle.DropDown;    }    public override object EditValue(ITypeDescriptorContext context,         IServiceProvider provider, object value)    {        var svc = (IWindowsFormsEditorService)provider            .GetService(typeof(IWindowsFormsEditorService));        var propertyToEdit = TypeDescriptor.GetProperties(value)            [nameof(MyTestClass.MyTestImageProperty)];        var ctx = new TypeDescriptionContext(            (Control)context.Instance, provider, value, propertyToEdit);        var editorControl = new MyTestClassEditorControl(svc, ctx, provider);        svc.DropDownControl(editorControl);        return editorControl.Result;    }}Editor controlpublic class MyTestClassEditorControl : Control{    public Object Result { get; private set; }    public MyTestClassEditorControl(IWindowsFormsEditorService service,        ITypeDescriptorContext context, IServiceProvider provider)     {        Result = context.Instance;        var button = new Button() { Text = "Choose Image",  AutoSize = true };        button.Click += (sender, e) =>        {            try            {                var imageProp = context.PropertyDescriptor;                var imageValue = imageProp.GetValue(context.Instance);                var editor = (UITypeEditor)imageProp                    .GetEditor(typeof(UITypeEditor));                var selectedImage = editor.EditValue(                    context, provider, imageValue);                imageProp.SetValue(context.Instance, selectedImage);                context.OnComponentChanging();                context.OnComponentChanged();                service.CloseDropDown();            }            catch (Exception ex)            {                MessageBox.Show(ex.ToString());            }        };        this.Controls.Add(button);        this.Height = 100;    }}TypeDescriptionContextpublic class TypeDescriptionContext : ITypeDescriptorContext{    Control control;    IServiceProvider provider;    object instannce;    PropertyDescriptor property;    public TypeDescriptionContext(Control control,        IServiceProvider provider, object instannce,        PropertyDescriptor property)    {        this.control = control;        this.provider = provider;        this.instannce = instannce;        this.property = property;    }    public IContainer Container => control.Site?.Container;    public object Instance => instannce;    public void OnComponentChanged() =>        GetService<IComponentChangeService>()        ?.OnComponentChanged(control, null, null, null);    public bool OnComponentChanging() => true;    public PropertyDescriptor PropertyDescriptor => property;    public object GetService(Type type) => provider?.GetService(type);    public T GetService<T>() => (T)this.GetService(typeof(T));}